import{_ as a,o,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"霍华德·马克思《投资最重要的事》精华","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/investment-methods/most-important-thing.md","filePath":"topics/investment-methods/most-important-thing.md"}'),r={name:"topics/investment-methods/most-important-thing.md"};function n(d,t,i,l,h,u){return o(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="霍华德·马克思《投资最重要的事》精华" tabindex="-1">霍华德·马克思《投资最重要的事》精华 <a class="header-anchor" href="#霍华德·马克思《投资最重要的事》精华" aria-label="Permalink to &quot;霍华德·马克思《投资最重要的事》精华&quot;">​</a></h1><blockquote><p>整理日期：2026-06-28 | 来源：视频精华总结，结合巴菲特、芒格、段永平实战心法</p></blockquote><hr><h2 id="一、投资前的灵魂拷问" tabindex="-1">一、投资前的灵魂拷问 <a class="header-anchor" href="#一、投资前的灵魂拷问" aria-label="Permalink to &quot;一、投资前的灵魂拷问&quot;">​</a></h2><p>每次下单前，四问自己：</p><ol><li><strong>公司质量</strong>：我是否真正理解其生意模式和现金流来源？是否因概念、风口或他人推荐而盲目购买？</li><li><strong>价格安全</strong>：当前价格是否存在安全边际？我是因便宜才买，还是因怕踏空而买？</li><li><strong>情绪影响</strong>：我是否被市场情绪左右？在众人恐惧时我是否贪婪，在众人贪婪时我是否更贪婪？</li><li><strong>长期持有</strong>：我是否做好了长期持有的准备？这笔钱是否为未来3-5年不用的闲钱？</li></ol><hr><h2 id="二、完整决策流程" tabindex="-1">二、完整决策流程 <a class="header-anchor" href="#二、完整决策流程" aria-label="Permalink to &quot;二、完整决策流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>筛选对象 → 估值 → 等待 → 出击 → 持有</span></span></code></pre></div><table tabindex="0"><thead><tr><th>阶段</th><th>核心动作</th><th>关键原则</th></tr></thead><tbody><tr><td>1. 筛选对象</td><td>在能力圈内寻找生意简单、现金流好的&quot;笨公司&quot;</td><td>避免看不懂的科技股和复杂金融衍生品</td></tr><tr><td>2. 估值</td><td>估算公司未来十年现金回报，判断当前价格是否打折</td><td>安全边际是第一原则</td></tr><tr><td>3. 等待</td><td>99%的时间都是无聊的</td><td>不要为了交易而交易，与焦虑共处</td></tr><tr><td>4. 出击</td><td>当&quot;又好又便宜&quot;的机会出现时</td><td>用&quot;盆&quot;去接，不是&quot;勺子&quot;</td></tr><tr><td>5. 持有</td><td>只要公司基本面未变、价格未高估</td><td>什么都不要做，大师的钱是&quot;坐着&quot;赚来的</td></tr></tbody></table><hr><h2 id="三、心态修炼" tabindex="-1">三、心态修炼 <a class="header-anchor" href="#三、心态修炼" aria-label="Permalink to &quot;三、心态修炼&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>内容</th></tr></thead><tbody><tr><td><strong>合理预期</strong></td><td>不追求完美预测或一夜暴富，真正高手追求年化10%-20%稳定回报</td></tr><tr><td><strong>耐心是美德</strong></td><td>复利需要时间。想快速变穷→赌博；愿意慢慢变富→钱来得比想象中快</td></tr><tr><td><strong>投资即修行</strong></td><td>考验的是耐心、诚实和定力。唯一能控制的就是&quot;不为清单&quot;</td></tr></tbody></table><hr><h2 id="四、与现有框架的结合" tabindex="-1">四、与现有框架的结合 <a class="header-anchor" href="#四、与现有框架的结合" aria-label="Permalink to &quot;四、与现有框架的结合&quot;">​</a></h2><h3 id="与投资三问的关系" tabindex="-1">与投资三问的关系 <a class="header-anchor" href="#与投资三问的关系" aria-label="Permalink to &quot;与投资三问的关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 成功依赖什么？（人 vs 系统） → 灵魂拷问第1题：理解生意模式</span></span>
<span class="line"><span>2. 能不能不依赖这个人？ → 筛选&quot;笨公司&quot;：简单、可复制</span></span>
<span class="line"><span>3. 能同时开多少家？ → 长期持有：复利需要规模和时间</span></span></code></pre></div><h3 id="与护城河的关系" tabindex="-1">与护城河的关系 <a class="header-anchor" href="#与护城河的关系" aria-label="Permalink to &quot;与护城河的关系&quot;">​</a></h3><p>马克思的&quot;安全边际&quot;强调价格，巴菲特的&quot;护城河&quot;强调质量，二者互补：</p><ul><li><strong>护城河</strong>决定&quot;好不好&quot;</li><li><strong>安全边际</strong>决定&quot;便不便宜&quot;</li><li>只有当&quot;又好又便宜&quot;同时成立时，才触发&quot;用盆接&quot;的出击信号</li></ul><hr><h2 id="五、核心理念提炼" tabindex="-1">五、核心理念提炼 <a class="header-anchor" href="#五、核心理念提炼" aria-label="Permalink to &quot;五、核心理念提炼&quot;">​</a></h2><blockquote><p>投资中最重要的不是&quot;买什么&quot;，而是&quot;什么时候买&quot;和&quot;愿意等多久&quot;。</p></blockquote><blockquote><p>99%的时间什么都不做，1%的时间用尽全力。</p></blockquote><blockquote><p>我们唯一能控制的，就是自己的&quot;不为清单&quot;。</p></blockquote>`,25)])])}const q=a(r,[["render",n]]);export{c as __pageData,q as default};
